<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useApp} from '../stores/app';import Icon from '../components/Icon.vue';import {encryptBackup,decryptBackup} from '../core/backup';import type {Snapshot} from '../core/models';
const navigator=window.navigator,confirm=window.confirm.bind(window);
const app=useApp(),profile=ref({...app.data.profile}),message=ref(''),password=ref(''),confirmation=ref(''),busy=ref(false),backupText=ref(''),restore=ref<Snapshot|null>(null),offline=ref('Checking offline installation…'),persistent=ref('Not requested'),storage=ref('');
onMounted(async()=>{if(!('serviceWorker' in navigator)){offline.value='Service workers unavailable in this browser.';return;}const reg=await navigator.serviceWorker.getRegistration();offline.value=reg?.active?'Offline app shell installed. Test by closing and reopening in airplane mode.':'Offline shell not yet active. Production HTTPS or localhost is required. Reload after the first installation.';if(navigator.storage){const estimate=await navigator.storage.estimate();storage.value=`${((estimate.usage||0)/1024/1024).toFixed(1)} MB used by this origin`;persistent.value=await navigator.storage.persisted()?'Persistent storage granted':'Best-effort browser storage';}});
async function attempt(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await fn();}catch(e){message.value=e instanceof Error?e.message:'Action failed.';}finally{busy.value=false;}}
async function save(){profile.value.name=profile.value.name.trim();if(!profile.value.name)throw Error('Enter a display name.');app.data.profile={...profile.value};await app.save();message.value='Profile and preferences saved.';}
async function exportData(){if(password.value!==confirmation.value)throw Error('Backup passwords do not match.');const text=await encryptBackup(app.data,password.value);const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='ironpulse-backup-'+app.today+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);password.value=confirmation.value='';message.value='Encrypted backup created. Keep the file and password somewhere safe.';}
async function readFile(event:Event){restore.value=null;backupText.value='';const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>20_000_000){message.value='Choose a backup under 20 MB.';return;}backupText.value=await file.text();}
async function preview(){restore.value=await decryptBackup(backupText.value,password.value);}
async function confirmRestore(){if(!restore.value)return;await app.save();const previous=app.data;app.data=restore.value;try{await app.save();}catch(e){app.data=previous;throw e;}profile.value={...app.data.profile};restore.value=null;backupText.value='';password.value=confirmation.value='';message.value='Backup restored successfully.';}
</script>
<template><section class="page-heading"><div><div class="eyebrow">MAKE IT PERSONAL</div><h1>Your workspace. <span>Your rules.</span></h1><p>Set your goals and keep ownership of your data.</p></div></section><p v-if="message" class="notice" role="status">{{message}}</p><div class="two-columns"><section class="card"><div class="section-title"><h3>Profile & goals</h3><Icon name="Target"/></div><form class="form-grid" @submit.prevent="attempt(save)"><label class="span-2">Display name<input v-model="profile.name" maxlength="60" required></label><label>Starting weight (kg)<input v-model.number="profile.weight" type="number" min="0" max="400" step="0.1" required></label><label>Height (cm)<input v-model.number="profile.height" type="number" min="0" max="250" step="1" required></label><label>Goal weight (kg)<input v-model.number="profile.targetWeight" type="number" min="0" max="400" step="0.1" required></label><label>Primary goal<select v-model="profile.goal"><option>Build muscle</option><option>Gain weight</option><option>Increase strength</option><option>General fitness</option><option>Maintain weight</option><option>Lose fat</option></select></label><label>Daily calorie target<input v-model.number="profile.calorieTarget" type="number" min="0" max="10000" step="1" required></label><label>Daily protein target (g)<input v-model.number="profile.proteinTarget" type="number" min="0" max="500" step="1" required></label><p class="fine muted span-2">Leave 0 for any measurement or target you prefer not to set. Targets are manually chosen; no clinical or nutrition assessment is made.</p><label>Appearance<select v-model="profile.theme"><option value="dark">Dark</option><option value="light">Light</option></select></label><label class="check-label"><input v-model="profile.reducedMotion" type="checkbox">Reduce motion</label><button class="button primary span-2" :disabled="busy">Save preferences<Icon name="Check"/></button></form><div class="callout"><strong>One private workspace</strong><p>This release has no account login or PIN lock. Records are stored unencrypted in this browser; protect your device. Multiple encrypted profiles are a later stage.</p></div></section><div class="stack"><section class="card"><div class="section-title"><h3>Offline installation</h3><Icon name="Download"/></div><p>{{offline}}</p><ol class="steps"><li>Open the production website once while online and allow its files to finish loading.</li><li>On Android, use your browser’s install option. On iPhone, open in Safari and choose Share → Add to Home Screen.</li><li>Open once from the home screen, then test in airplane mode.</li></ol><p class="fine muted">Browser support varies. Installed assets can work during a hosting outage, but browser storage can still be removed. Native Android and iOS packages are not included.</p><div class="storage-row"><span>{{persistent}}<small>{{storage}}</small></span><button class="button secondary" @click="attempt(async()=>{persistent=navigator.storage?.persist?((await navigator.storage.persist())?'Persistent storage granted':'Browser did not grant persistence'):'Unavailable';})">Protect storage</button></div></section><section class="card"><div class="section-title"><h3>Encrypted backup</h3><Icon name="ShieldCheck"/></div><p class="muted">Back up regularly. Device loss or browser cleanup can erase your records. There is no password recovery.</p><label>Backup password (at least 12 characters)<input v-model="password" type="password" autocomplete="new-password" minlength="12"></label><label>Confirm password for export<input v-model="confirmation" type="password" autocomplete="new-password"></label><button class="button primary full" :disabled="busy||password.length<12" @click="attempt(exportData)"><Icon name="Download"/>Export encrypted backup</button><hr><label>Restore from backup<input type="file" accept=".json,application/json" @change="readFile"></label><button class="button secondary full" :disabled="busy||!backupText||!password" @click="attempt(preview)">Decrypt & preview</button><div v-if="restore" class="callout"><strong>Restore {{restore.profile.name}}?</strong><p>{{restore.sessions.length}} sessions · {{restore.meals.length}} meals · {{restore.weights.length}} weigh-ins.</p><p>This replaces all records in this workspace. Export your current records first.</p><div class="button-row"><button class="button primary" :disabled="busy" @click="attempt(confirmRestore)">Replace & restore</button><button class="button secondary" @click="restore=null">Cancel</button></div></div></section><section class="card"><h3>Delete this workspace</h3><p class="muted">Permanently remove all training, meal, profile, and weight records from this browser.</p><button class="button danger" :disabled="busy" @click="attempt(async()=>{if(confirm('Permanently delete all IRONPULSE records on this device? This cannot be undone.')){await app.reset();profile={...app.data.profile};message='Workspace deleted.';}})"><Icon name="Trash2" :size="16"/>Delete all local data</button></section></div></div></template>
